function activitySummary(item: JsonRecord) {
  const payload = item.payload || {};
  const text = (value: unknown) => typeof value === 'string' ? value.trim() : '';
  const summary = text(item.summary) || text(payload.summary);
  if (summary) return summary.slice(0, 300);
  const parts: string[] = [];
  if (text(payload.direction)) parts.push(titleCase(payload.direction));
  const phone = text(payload.phone) || text(payload.from_number) || text(payload.to_number);
  if (phone) parts.push(phone);
  if (typeof payload.duration === 'number' && Number.isFinite(payload.duration)) parts.push(`${Math.floor(payload.duration / 60)}m ${Math.floor(payload.duration % 60)}s`);
  const subject = text(payload.subject) || text(payload.email_subject);
  if (subject) parts.push(subject);
  const body = text(item.body) || text(payload.body) || text(payload.message);
  if (body) parts.push(body.slice(0, 240));
  const document = text(payload.filename) || text(payload.document_type);
  if (document) parts.push(titleCase(document));
  if (text(payload.command)) parts.push(titleCase(payload.command));
  if (typeof payload.confidence === 'number' && Number.isFinite(payload.confidence)) parts.push(`Confidence ${Math.round(payload.confidence * 100)}%`);
  if (!parts.length && text(payload.transcript)) return payload.transcript.slice(0, 240);
  return parts.join(' · ') || 'Recorded against this contact.';
}
